1	import fs from 'fs';
2	import path from 'path';
3	import { parseFrontmatter, Frontmatter } from './frontmatter';
4	import { markdownToHtml } from './markdown';
5	import { TemplateEngine } from './templates';
6	import { PluginManager, PluginContext } from './plugin';
7	
8	export interface PageData {
9	  slug: string;
10	  filename: string;
11	  frontmatter: Frontmatter;
12	  content: string;
13	  html: string;
14	}
15	
16	export async function readMarkdownFiles(contentDir: string): Promise<string[]> {
17	  if (!fs.existsSync(contentDir)) {
18	    throw new Error(`Content directory not found: ${contentDir}`);
19	  }
20	
21	  const files = fs.readdirSync(contentDir);
22	  return files.filter((file) => file.endsWith('.md'));
23	}
24	
25	export async function parseMarkdownFile(
26	  filePath: string
27	): Promise<PageData> {
28	  const content = fs.readFileSync(filePath, 'utf-8');
29	  const { frontmatter, content: markdown } = parseFrontmatter(content);
30	  const html = markdownToHtml(markdown);
31	  const filename = path.basename(filePath);
32	  const slug = filename.replace(/\.md$/, '');
33	
34	  return {
35	    slug,
36	    filename,
37	    frontmatter,
38	    content: markdown,
39	    html,
40	  };
41	}
42	
43	export async function generatePages(
44	  contentDir: string,
45	  outputDir: string,
46	  templateEngine?: TemplateEngine,
47	  pluginManager?: PluginManager
48	): Promise<PageData[]> {
49	  if (!fs.existsSync(outputDir)) {
50	    fs.mkdirSync(outputDir, { recursive: true });
51	  }
52	
53	  const files = await readMarkdownFiles(contentDir);
54	  const pages: PageData[] = [];
55	  const context: PluginContext = { contentDir, outputDir, templatesDir: '' };
56	
57	  for (const file of files) {
58	    const filePath = path.join(contentDir, file);
59	    const pageData = await parseMarkdownFile(filePath);
60	    pages.push(pageData);
61	
62	    if (pluginManager) {
63	      await pluginManager.executeFileHook(pageData, context);
64	    } else {
65	      pageData.html = markdownToHtml(pageData.content);
66	    }
67	
68	    const outputPath = path.join(outputDir, `${pageData.slug}.html`);
69	    const html = templateEngine
70	      ? generatePageHtmlWithTemplate(pageData, templateEngine)
71	      : generatePageHtml(pageData);
72	    fs.writeFileSync(outputPath, html, 'utf-8');
73	  }
74	
75	  return pages;
76	}
