78	export function generatePageHtml(page: PageData): string {
79	  const title = page.frontmatter.title || page.slug;
80	  const date = page.frontmatter.date ? `<p class="date">${page.frontmatter.date}</p>` : '';
81	  const tags =
82	    page.frontmatter.tags && Array.isArray(page.frontmatter.tags)
83	      ? `<div class="tags">${page.frontmatter.tags
84	          .map((tag) => `<span class="tag">${escapeHtml(String(tag))}</span>`)
85	          .join('')}</div>`
86	      : '';
87	
88	  return `<!DOCTYPE html>
89	<html lang="en">
90	<head>
91	  <meta charset="UTF-8">
92	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
93	  <title>${escapeHtml(title)}</title>
94	  <style>
95	    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 800px; margin: 0 auto; padding: 20px; line-height: 1.6; }
96	    h1, h2, h3 { margin-top: 1.5em; }
97	    .date { color: #666; font-size: 0.9em; }
98	    .tags { margin: 10px 0; }
99	    .tag { display: inline-block; background: #f0f0f0; padding: 4px 8px; margin: 4px 4px 4px 0; border-radius: 4px; font-size: 0.85em; }
100	    a { color: #0066cc; }
101	  </style>
102	</head>
103	<body>
104	  <a href="index.html">← Back to Index</a>
105	  <article>
106	    <h1>${escapeHtml(title)}</h1>
107	    ${date}
108	    ${tags}
109	    <div class="content">
110	      ${page.html}
111	    </div>
112	  </article>
113	</body>
114	</html>`;
115	}
116	
117	export function generateIndexHtml(pages: PageData[]): string {
118	  const sortedPages = pages.sort((a, b) => {
119	    const dateA = new Date(String(a.frontmatter.date) || 0).getTime();
120	    const dateB = new Date(String(b.frontmatter.date) || 0).getTime();
121	    return dateB - dateA;
122	  });
123	
124	  const pagesList = sortedPages
125	    .map((page) => {
126	      const title = page.frontmatter.title || page.slug;
127	      const date = page.frontmatter.date ? ` — ${page.frontmatter.date}` : '';
128	      return `<li><a href="${page.slug}.html">${escapeHtml(title)}</a>${date}</li>`;
129	    })
130	    .join('\n    ');
131	
132	  return `<!DOCTYPE html>
133	<html lang="en">
134	<head>
135	  <meta charset="UTF-8">
136	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
137	  <title>Site Index</title>
138	  <style>
139	    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 800px; margin: 0 auto; padding: 20px; line-height: 1.6; }
140	    h1 { margin-bottom: 1.5em; }
141	    ul { list-style: none; padding: 0; }
142	    li { margin: 12px 0; }
143	    a { color: #0066cc; text-decoration: none; }
144	    a:hover { text-decoration: underline; }
145	  </style>
146	</head>
147	<body>
148	  <h1>Site Index</h1>
149	  <ul>
150	    ${pagesList}
151	  </ul>
152	</body>
153	</html>`;
154	}
155	
156	export function generatePageHtmlWithTemplate(
157	  page: PageData,
158	  templateEngine: TemplateEngine
159	): string {
160	  const templateName = String(page.frontmatter.template || 'page');
161	  const layoutName = String(page.frontmatter.layout || 'default');
162	
163	  const context = {
164	    title: page.frontmatter.title || page.slug,
165	    slug: page.slug,
166	    filename: page.filename,
167	    date: page.frontmatter.date,
168	    tags: page.frontmatter.tags,
169	    content: page.html,
170	    ...page.frontmatter,
171	  };
172	
173	  const templateContent = templateEngine.renderTemplate(templateName, context);
174	
175	  if (templateEngine.hasLayout(layoutName)) {
176	    return templateEngine.renderPageWithLayout(templateContent, layoutName, context);
177	  }
178	
179	  return templateContent;
180	}
