182	export async function build(
183	  contentDir: string = './content',
184	  outputDir: string = './dist',
185	  templatesDir: string = './templates',
186	  pluginManager?: PluginManager
187	): Promise<void> {
188	  if (!fs.existsSync(outputDir)) {
189	    fs.mkdirSync(outputDir, { recursive: true });
190	  }
191	
192	  const context: PluginContext = { contentDir, outputDir, templatesDir };
193	
194	  if (pluginManager) {
195	    await pluginManager.executeHook('onStart', context);
196	    await pluginManager.executeHook('beforeBuild', context);
197	  }
198	
199	  let templateEngine: TemplateEngine | undefined;
200	  if (pluginManager) {
201	    const templatePlugin = pluginManager.getPlugin('template-plugin') as any;
202	    if (templatePlugin && templatePlugin.getTemplateEngine) {
203	      templateEngine = templatePlugin.getTemplateEngine();
204	    }
205	  } else if (fs.existsSync(templatesDir)) {
206	    templateEngine = new TemplateEngine({
207	      templatesDir,
208	      layoutsDir: path.join(templatesDir, 'layouts'),
209	      partialsDir: path.join(templatesDir, 'partials'),
210	    });
211	  }
212	
213	  const pages = await generatePages(contentDir, outputDir, templateEngine, pluginManager);
214	  const indexHtml = generateIndexHtml(pages);
215	  fs.writeFileSync(path.join(outputDir, 'index.html'), indexHtml, 'utf-8');
216	
217	  if (pluginManager) {
218	    await pluginManager.executeHook('afterBuild', context, pages);
219	    await pluginManager.executeHook('onEnd', context);
220	  }
221	}
222	
223	function escapeHtml(text: string): string {
224	  const escapeMap: { [key: string]: string } = {
225	    '&': '&amp;',
226	    '<': '&lt;',
227	    '>': '&gt;',
228	    '"': '&quot;',
229	    "'": '&#39;',
230	  };
231	  return text.replace(/[&<>"']/g, (char) => escapeMap[char]);
232	}
